style.css:
/* Background image */
body {
    background-image: url("https://i.imgur.com/vmAUB8n.jpeg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
}

/* Soft blur overlay for readability */
html::before {
    content: "";
    position: fixed;
    inset: 0;
    backdrop-filter: blur(6px);
    background: rgba(255, 240, 245, 0.35); /* soft pink */
    z-index: -1;
}

/* Make boxes look aesthetic instead of solid white */
div, section, main, header, footer, nav {
    background: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(8px);
    border-radius: 12px;
}

/* Text color to match vibe */
body, * {
    color: #4a3b3b !important;
    font-family: "Segoe UI", "Arial", sans-serif !important;
}
